import { describe, expect, it } from "vitest";
import reviewSql from "../seed/review.sql?raw";
import { addDays, tollTimeIn } from "../src/domain/time";
import type { HomeResponse } from "../src/features/home/contract";
import type { FriendsInsights, SchoolInsights } from "../src/features/insights/contract";
import type { PeopleResponse } from "../src/features/people/contract";
import type { AuthSession } from "../src/features/shared/contract";
import { json } from "./accounts";
import { call, env } from "./helpers";
import "./school-fixture";

// seed/review.sql is regenerated by `pretest`, so this checks the script as it is today.
describe("review account seed (E10.46)", () => {
  it("applies, signs in with the review code and gives every card something to show", async () => {
    const statements = reviewSql
      .split(/;\n/)
      .map((s) => s.trim())
      .filter((s) => s && !s.startsWith("--"));
    for (let i = 0; i < statements.length; i += 50) {
      await env.DB.batch(statements.slice(i, i + 50).map((s) => env.DB.prepare(s)));
    }
    const ids = [...reviewSql.matchAll(/'(00000000-0000-4000-8000-\d{12})'/g)].map((m) => m[1]);
    const recompute = await call("/v1/admin/recompute", {
      method: "POST",
      token: env.ADMIN_TOKEN,
      json: { userIds: [...new Set(ids)], days: 60 },
    });
    expect(recompute.status).toBe(200);

    expect(
      (await call("/v1/auth/email/start", { method: "POST", json: { email: env.REVIEW_EMAIL } })).status,
    ).toBe(204);
    const session = await json<AuthSession>(
      call("/v1/auth/email/verify", {
        method: "POST",
        json: { email: env.REVIEW_EMAIL, code: env.REVIEW_CODE, deviceId: "review-phone" },
      }),
    );
    expect(session.user.handle).toBe("review");
    const token = session.token;

    const home = await json<HomeResponse>(call("/v1/home", { token }));
    expect(home.friends).toHaveLength(5);
    expect(home.pinned.map((p) => p.kind).sort()).toEqual(["loosened", "removal", "silence"]);
    expect(home.friendsHeldPercent).not.toBeNull();

    const people = await json<PeopleResponse>(call("/v1/people", { token }));
    expect(people.mutuals.map((m) => m.user.handle)).toEqual(["fay"]);
    expect(people.school?.name).toBe("University of Waterloo");

    // Last week is complete whatever hour this runs, so the cards are certain to have data.
    const week = addDays(tollTimeIn("America/Toronto", Date.now(), 4).week, -7);
    const friends = await json<FriendsInsights>(call(`/v1/insights/friends?week=${week}`, { token }));
    expect(friends.distribution).not.toBeNull();
    expect(friends.weekly.filter((w) => w.heldPercent !== null)).toHaveLength(8);

    const school = await json<SchoolInsights>(call(`/v1/insights/school?week=${week}`, { token }));
    expect(school.enough).toBe(true);
    expect(school.examWeeks).toHaveLength(1);
  });
});
